import csv
import statistics
from datetime import datetime


def load_readings(path):
    """Read temperature readings from a CSV with columns: sensor, timestamp, celsius."""
    readings = []
    with open(path, newline="") as f:
        for row in csv.DictReader(f):
            readings.append(
                (row["sensor"], datetime.fromisoformat(row["timestamp"]), float(row["celsius"]))
            )
    return readings


def by_sensor(readings):
    groups = {}
    for sensor, ts, value in readings:
        groups.setdefault(sensor, []).append((ts, value))
    for values in groups.values():
        values.sort()
    return groups


def daily_means(values):
    days = {}
    for ts, value in values:
        days.setdefault(ts.date(), []).append(value)
    return {day: statistics.mean(v) for day, v in sorted(days.items())}


def find_spikes(values, threshold=5.0):
    spikes = []
    for (t1, v1), (t2, v2) in zip(values, values[1:]):
        if abs(v2 - v1) >= threshold:
            spikes.append((t2, v2 - v1))
    return spikes


def to_fahrenheit(celsius):
    return celsius * 9 / 5 + 32


def report(path):
    groups = by_sensor(load_readings(path))
    for sensor, values in groups.items():
        means = daily_means(values)
        spikes = find_spikes(values)
        print(f"{sensor}: {len(values)} readings, {len(means)} days, {len(spikes)} spikes")
