```javascript
const fs = require('fs');
const path = require('path');
const https = require('https');

function readConfig(file, callback) {
  fs.readFile(file, 'utf8', function (err, data) {
    if (err) return callback(err);
    try {
      callback(null, JSON.parse(data));
    } catch (e) {
      callback(e);
    }
  });
}

function fetchJson(url, callback) {
  https.get(url, function (res) {
    let body = '';
    res.on('data', function (chunk) { body += chunk; });
    res.on('end', function () {
      if (res.statusCode !== 200) {
        return callback(new Error('HTTP ' + res.statusCode));
      }
      try {
        callback(null, JSON.parse(body));
      } catch (e) {
        callback(e);
      }
    });
  }).on('error', callback);
}

function saveReport(dir, name, report, callback) {
  fs.mkdir(dir, { recursive: true }, function (err) {
    if (err) return callback(err);
    fs.writeFile(path.join(dir, name), JSON.stringify(report, null, 2), callback);
  });
}

function run(configFile, done) {
  readConfig(configFile, function (err, config) {
    if (err) return done(err);
    const results = [];
    let pending = config.endpoints.length;
    if (pending === 0) return done(null, results);
    config.endpoints.forEach(function (endpoint) {
      fetchJson(endpoint.url, function (err, data) {
        if (err) {
          results.push({ name: endpoint.name, ok: false, error: err.message });
        } else {
          results.push({ name: endpoint.name, ok: true, items: data.items.length });
        }
        pending -= 1;
        if (pending === 0) {
          saveReport(config.outputDir, 'report.json', results, function (err) {
            if (err) return done(err);
            done(null, results);
          });
        }
      });
    });
  });
}

module.exports = { run, readConfig, fetchJson, saveReport };
