def parse_duration(text: str) -> int:
    """'1h30m' -> 5400, '45s' -> 45, '2h' -> 7200. Raises ValueError on bad input."""
    units = {'h': 3600, 'm': 60, 's': 1}
    total, number = 0, ''
    for ch in text.strip():
        if ch.isdigit():
            number += ch
        elif ch in units and number:
            total += int(number) * units[ch]
            number = ''
        else:
            raise ValueError(text)
    if number or not total and text.strip() != '0s':
        raise ValueError(text)
    return total
